/**
 * Live Camera Index playable-count pins (map bundle item 6, 2026-10-31).
 *
 * The Index's dataset (src/data/live-camera-index.json, generated by
 * tools/build-live-camera-index.mjs) carries a PLAYABLE figure: the
 * served records the WorldEye player could open, derived with the
 * player's own rule (lib/camera-preview previewMedia, mirrored in the
 * generator). These pins keep the published dataset honest:
 *  - the playable total reconciles with its per-kind tally;
 *  - the page dataset and the downloadable dataset cannot drift;
 *  - the site-stats mirror of the snapshot agrees with the dataset;
 *  - the generator still carries the mirrored derivation.
 */
import { describe, it, expect } from "vitest";
import { readFileSync } from "fs";
import { join } from "path";
import indexData from "@/data/live-camera-index.json";
import { CAMERA_INDEX_SNAPSHOT } from "@/lib/site-stats";

const D = indexData as unknown as {
  generatedAt: string;
  totals: { served: number; servedCountries: number; playable: number };
  playableByKind: Array<{ name: string; count: number }>;
};

describe("Live Camera Index — playable derivation", () => {
  it("the playable total reconciles with its per-kind tally", () => {
    const sum = D.playableByKind.reduce((n, k) => n + k.count, 0);
    expect(sum).toBe(D.totals.playable);
  });

  it("playable is a true subset of served, in player kinds only", () => {
    expect(D.totals.playable).toBeGreaterThan(0);
    expect(D.totals.playable).toBeLessThanOrEqual(D.totals.served);
    for (const k of D.playableByKind) {
      expect(["jpg", "hls", "mp4", "mjpeg"]).toContain(k.name);
    }
  });

  it("the page dataset and the downloadable dataset are the same file", () => {
    const pub = readFileSync(
      join(process.cwd(), "public/data/live-camera-index-2026.json"),
      "utf8",
    );
    expect(JSON.parse(pub)).toEqual(JSON.parse(JSON.stringify(indexData)));
  });

  it("the site-stats snapshot mirror agrees with the dataset", () => {
    expect(CAMERA_INDEX_SNAPSHOT.servedUniqueCameras).toBe(D.totals.served);
    expect(CAMERA_INDEX_SNAPSHOT.servedCountries).toBe(D.totals.servedCountries);
    expect(CAMERA_INDEX_SNAPSHOT.playableCameras).toBe(D.totals.playable);
    const label = new Intl.DateTimeFormat("en-GB", {
      day: "numeric",
      month: "long",
      year: "numeric",
      timeZone: "UTC",
    }).format(new Date(D.generatedAt));
    expect(CAMERA_INDEX_SNAPSHOT.snapshotDateLabel).toBe(label);
  });

  it("the generator still derives playable with the mirrored player rule", () => {
    const gen = readFileSync(
      join(process.cwd(), "tools/build-live-camera-index.mjs"),
      "utf8",
    );
    expect(gen).toContain("function playableKind(cam)");
    expect(gen).toContain("previewMedia");
    expect(gen).toContain("playable,");
  });
});
